//! Legacy binary Word failure semantics. Valid `.doc` fixtures are generated by
//! Word for the real-app QA run instead of checking an opaque binary into Git.
use pkms_core::SourceFormat;
use pkms_worker::{WorkerRequest, WorkerResult, execute};

fn request(root: &std::path::Path) -> WorkerRequest {
    WorkerRequest {
        protocol_version: 1,
        job_id: uuid::Uuid::new_v4().to_string(),
        attempt: 1,
        lease_token: uuid::Uuid::new_v4().to_string(),
        source_version_id: uuid::Uuid::new_v4().to_string(),
        input_path: root.join("input.doc"),
        format: SourceFormat::Doc,
        output_dir: root.to_owned(),
        pdfium_library_path: None,
        content_type: None,
        ocr: None,
    }
}

fn failure_code(request: &WorkerRequest) -> String {
    match execute(request).result {
        WorkerResult::Failure { code } => code,
        other => panic!("expected a failure result, got {other:?}"),
    }
}

#[test]
fn a_file_without_the_ole_header_reports_the_doc_specific_failure() {
    let root = tempfile::tempdir().unwrap();
    let request = request(root.path());
    std::fs::write(
        &request.input_path,
        b"plain text named as a legacy Word file",
    )
    .unwrap();
    assert_eq!(failure_code(&request), "doc_not_container");
}
